use vstd::prelude::*;

verus! {

    /// Returns the maximum element of a non‐empty vector of i8.
    /// 
    /// Requires:
    ///   - `a.len() > 0` (the vector is non‐empty)
    ///
    /// Ensures:
    ///   - there exists a valid index `i` in the vector such that `result == a@[i]`
    ///   - for every index `j` in the vector, `a@[j] <= result`
    fn nanmax(a: Vec<i8>) -> (result: i8)
        requires
            a.len() > 0,
        ensures
            // result comes from some position in the vector
            exists |i: nat| i < a@.len() && result == a@[i],
        ensures
            // result is at least as large as every element
            forall |j: nat| j < a@.len() ==> a@[j] <= result,
    {
        // Start with the first element as the provisional max
        let mut result: i8 = a[0];
        let mut i: usize = 1;

        // Scan the rest of the vector
        while i < a.len()
            invariant
                // we have processed exactly the first i elements
                1 <= i && i <= a.len(),
                // result is the maximum of a[0..i)
                exists |k: nat| k < i && result == a@[k],
                forall |k: nat| k < i ==> a@[k] <= result,
            decreases a.len() - i,
        {
            let x: i8 = a[i];
            if x > result {
                result = x;
            }
            i = i + 1;
        }

        // When the loop exits, i == a.len(), so the invariants yield
        // 1) ∃ k < a.len() . result == a@[k]
        // 2) ∀ k < a.len() . a@[k] <= result
        result
    }
}

